import java.util.*;import java.util.zip.*;import java.security.*;public class JarMembers{static String h(String s)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}public static void main(String[]a)throws Exception{System.setOut(new java.io.PrintStream(System.out,true,java.nio.charset.StandardCharsets.UTF_8));try(var z=new ZipFile(a[0])){for(var e:Collections.list(z.entries())){if(!e.getName().endsWith(".class"))continue;var c=OpeningDelta.read(z.getInputStream(e).readAllBytes(),0);System.out.println("C	"+c.name);for(var f:c.fields)System.out.println("F	"+c.name+"	"+f.name+"	"+f.desc);for(var m:c.methods)System.out.println("M	"+c.name+"	"+m.name+"	"+m.desc+"	"+h(OpeningDelta.norm(m)));}}}}